  update(id: number, quantity: number) {
    return http.patch<ApiResponse<Cart>>(`/cart/${id}`, { quantity });
  },
  remove(id: number) {
    return http.delete<ApiResponse<unknown>>(`/cart/${id}`);
  },
};

